 "content": "def transform(grid):
    """Collapse uniform nonzero horizontal/vertical bands to one cell."""
    h, w = len(grid), len(grid[0])

    def dominant_nonzero(line):
        counts = {}
        for value in line:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1
        if not counts:
            return None, 0
        color = max(counts, key=counts.get)
        return color, counts[color]

    horizontal = []
    for r, row in enumerate(grid):
        color, count = dominant_nonzero(row)
        if color is not None and count >= 2:
            horizontal.append(r)

    vertical = []
    for c in range(w):
        color, count = dominant_nonzero([grid[r][c] for r in range(h)])
        if color is not None and count >= 2:
            vertical.append(c)

    def representative_indices(length, separators):
        selected = []
        start = 0
        for sep in separators:
            if start < sep:
                selected.append(start)
            selected.append(sep)
            start = sep + 1
        if start < length:
            selected.append(start)
        return selected

    rows = representative_indices(h, horizontal)
    cols = representative_indices(w, vertical)
    return [[grid[r][c] for c in cols] for r in rows]
